const tool = {"name":"select_excerpts","description":"Select the passages from the sources genuinely relevant to the chosen angle.","input_schema":{"type":"object","required":["excerpts"],"properties":{"excerpts":{"type":"array","items":{"type":"object","required":["source_url","text","reason"],"properties":{"source_url":{"type":"string"},"text":{"type":"string"},"reason":{"type":"string"}}}}}}};
const content = `You are selecting source excerpts for a content angle.\n\nChosen angle: ${$('Fetch Angle Row').first().json.working_title}\nThesis: ${$('Fetch Angle Row').first().json.thesis}\nSection shape: ${JSON.stringify($('Fetch Angle Row').first().json.section_shape)}\n\nSources:\n${$('Count Scraped Sources').first().json.sourcesText}\n\nSelect every passage genuinely relevant to this specific angle - not the whole source, just passages that actually support it. For each, give the exact excerpt text (a real quote, not a paraphrase), which source URL it came from, and a one-line reason. If nothing in a source is relevant, select nothing from it. Return an empty excerpts array if truly nothing across all sources supports this angle.`;
const requestBody = JSON.stringify({
  model: 'claude-sonnet-5',
  max_tokens: 4000,
  tools: [tool],
  tool_choice: { type: 'tool', name: 'select_excerpts' },
  messages: [{ role: 'user', content }]
});
return [{ json: { requestBody } }];

const err = $json.error || {};
const message = (err.message || JSON.stringify(err) || 'Unknown Claude API error').slice(0, 500);
return [{ json: { requestId: $('Config').first().json.request_id, message } }];

const toolUse = $json.content.find(c => c.type === 'tool_use');
let excerpts = toolUse.input.excerpts;
if (typeof excerpts === 'string') { try { excerpts = JSON.parse(excerpts); } catch { excerpts = []; } }
if (!Array.isArray(excerpts) && excerpts && typeof excerpts === 'object') excerpts = Object.values(excerpts);
if (!Array.isArray(excerpts)) excerpts = [];
excerpts = excerpts.filter(e => e && typeof e === 'object');
const sources = $('Count Scraped Sources').first().json.sources;
const requestId = $('Config').first().json.request_id;
const mapped = excerpts.map(e => {
  const source = sources.find(s => s.url === e.source_url);
  return { request_id: requestId, source_id: source ? source.id : null, text: e.text, reason: e.reason };
}).filter(e => e.source_id);
return [{ json: { requestId, excerpts: mapped } }];

const excerpts = $input.all().map(i => i.json);
const withReason = excerpts.map((e, i) => `[${i}] ${e.text} (reason selected: ${e.reason})`).join('

');
const plain = excerpts.map((e, i) => `[${i}] Source: ${(e.sources && e.sources.url) || e.source_id}
${e.text}`).join('

');
return [{ json: { excerpts, excerptsTextWithReason: withReason, excerptsTextPlain: plain } }];

const tool = {"name":"write_article","description":"Write the full grounded article for the chosen angle.","input_schema":{"type":"object","required":["title","body_markdown","secondary_keywords"],"properties":{"title":{"type":"string"},"body_markdown":{"type":"string"},"secondary_keywords":{"type":"array","items":{"type":"string"}}}}};
const content = `Write a full SEO article grounded only in the excerpts below - no unsupported claims or invented statistics. If the excerpts can't adequately support the desired length, write a shorter, fully-grounded article and say so isn't needed in the output, just write what's honestly supportable.

Working title: ${$('Fetch Angle Row').first().json.working_title}
Thesis: ${$('Fetch Angle Row').first().json.thesis}
Section shape: ${JSON.stringify($('Fetch Angle Row').first().json.section_shape)}
Primary keyword (must appear naturally, including in a heading): ${$('Fetch Request Row').first().json.primary_keyword}
Desired length: ${$('Fetch Request Row').first().json.desired_length || 'no specific target'}
Context from the manager: ${$('Fetch Request Row').first().json.context || 'none'}

Grounded excerpts (cite the source URL inline as [Source: url] after any claim drawn from it):
${$('Build Excerpts Text').first().json.excerptsTextWithReason}

Write in markdown with proper H1/H2 heading hierarchy.

House style: never use em dashes (the character U+2014) anywhere in the output. Use a full stop, a comma, a colon or parentheses instead. Do not state anything the excerpts do not support, and do not use hedging language to smuggle in a claim you cannot cite.`;
const requestBody = JSON.stringify({
  model: 'claude-sonnet-5',
  max_tokens: 4000,
  tools: [tool],
  tool_choice: { type: 'tool', name: 'write_article' },
  messages: [{ role: 'user', content }]
});
return [{ json: { requestBody } }];

const err = $json.error || {};
const message = (err.message || JSON.stringify(err) || 'Unknown Claude API error').slice(0, 500);
