const content = `Evaluate this article against the rubric. You have not seen how it was written or planned - judge only what's here.\n\nRubric: Score out of 100 across: Topic Relevance (20, floor 15), Source Grounding (20, floor 15), Factual Consistency (20, floor 15), Audience Fit (15, floor 6), SEO Fit (10, floor 4), Clarity (10, floor 4), Completeness (5, floor 2). Topic Relevance/Source Grounding/Factual Consistency are hard-block tier: if any scores below its floor, hard_block_triggered must be true regardless of the total. Verify every claim against the excerpt it cites and flag any claim citing nothing. Always populate weakest_criteria_suggestions, even on a passing score - a passing draft can still have one mediocre criterion worth naming.\n\nArticle:\n${$('Insert Section v1').first().json.body_markdown}\n\nGrounded excerpts it should be checked against:\n${$('Build Excerpts Text').first().json.excerptsTextPlain}`;
const requestBody = JSON.stringify({
  model: 'claude-opus-5',
  max_tokens: 3000,
  tools: [tool],
  tool_choice: { type: 'tool', name: 'evaluate_article' },
  messages: [{ role: 'user', content }]
});
return [{ json: { requestBody } }];

const err = $json.error || {};
const message = (err.message || JSON.stringify(err) || 'Unknown Claude API error').slice(0, 500);
return [{ json: { requestId: $('Config').first().json.request_id, message } }];

const c = $json.criteria || [];
const floor = (name, f) => { const crit = c.find(x => x.name.toLowerCase().includes(name)); return crit ? crit.score < f : false; };
const hardBlock = $json.hard_block_triggered || floor('topic', 15) || floor('grounding', 15) || floor('factual', 15) || floor('consistency', 15);
const score = $json.overall_score;
let decision;
if (hardBlock) { decision = score < 60 ? 'reject' : 'revise'; }
else if (score >= 85) { decision = 'pass'; }
else if (score >= 60) { decision = 'revise'; }
else { decision = 'reject'; }
return [{ json: { ...$json, hardBlock, decision } }];

